import { NextResponse } from "next/server";
import { createClient } from "@/lib/supabase/server";
import { GoogleGenerativeAI } from "@google/generative-ai";

const genAI = new GoogleGenerativeAI(process.env.GEMINI_API_KEY || "");

export async function POST(request: Request) {
  if (!process.env.GEMINI_API_KEY) {
    return new NextResponse(JSON.stringify({ error: "Missing GEMINI_API_KEY." }), {
      status: 500,
      headers: { "Content-Type": "application/json" },
    });
  }

  const supabase = await createClient();
  const { data: { user } } = await supabase.auth.getUser();

  if (!user) {
    return new NextResponse(JSON.stringify({ error: "Unauthorized" }), {
      status: 401,
      headers: { "Content-Type": "application/json" },
    });
  }

    const { address, beds, baths, sqft, price, features, tone, styleId } = await request.json();
  
    if (!address) {
      return new NextResponse(JSON.stringify({ error: "Address is required" }), {
        status: 400,
        headers: { "Content-Type": "application/json" },
      });
    }
  
    // 4. Check Subscription and Usage
    const { data: subscription } = await supabase
      .from("subscriptions")
      .select("status")
      .eq("user_id", user.id)
      .eq("status", "active")
      .single();
  
    if (!subscription) {
      const today = new Date().toISOString().split('T')[0];
      const { count } = await supabase
        .from("usage_logs")
        .select("*", { count: "exact", head: true })
        .eq("user_id", user.id)
        .eq("tool_name", "real-estate")
        .gte("created_at", today);
  
      if (count !== null && count >= 3) {
        return new NextResponse(
          JSON.stringify({
            error: "Free limit reached (3/3). Please upgrade to Pro for unlimited listings.",
            isQuotaExceeded: true
          }),
          { 
            status: 403,
            headers: { "Content-Type": "application/json" },
          }
        );
      }
    }
  
      // 5. Fetch Style Samples if provided
      let styleInstructions = "";
      if (styleId) {
        const { data: samples } = await supabase
          .from("voice_samples")
          .select("content")
          .eq("profile_id", styleId)
          .limit(5);      
      if (samples && samples.length > 0) {
        styleInstructions = `
        CRITICAL: You must mimic the following writing style exactly. 
        Pay attention to the sentence length, vocabulary choice, use of emojis, and overall rhythm.
        
        EXAMPLES OF THE TARGET STYLE:
        ${samples.map((s, i) => `Sample ${i+1}: "${s.content}"`).join("\n\n")}
        
        Now, apply this exact style to the new real estate listing below.`;
      }
    }
  
    try {
      const model = genAI.getGenerativeModel({ model: "gemini-flash-latest" });
  
      const prompt = `You are a high-end Real Estate Copywriter. Your goal is to write a compelling property description for the following listing:
  
      Address/Neighborhood: ${address}
      Price: ${price}
      Beds: ${beds}
      Baths: ${baths}
      Sq Ft: ${sqft}
      Key Features: ${features}
      Tone of Voice: ${tone}
      ${styleInstructions}
  
      Instructions:
      1. **Structure:** Start with a catchy headline.
      2. **Opening:** Hook the reader immediately with the best feature.
      3. **Flow:** Describe the experience of living in the home, moving from room to room or from interior to exterior.
      4. **Neighborhood:** Mention the lifestyle benefits of the location.
      5. **Call to Action:** End with a strong invitation to schedule a viewing.
      6. **Constraints:** Keep it between 200 and 400 words. Do not use generic cliches like "must see" unless earned.
  
      Write the listing now.`;
  
      const result = await model.generateContent(prompt);
      const response = await result.response;
      const listing = response.text();
  
      // 6. Log Usage
      await supabase.from("usage_logs").insert({
        user_id: user.id,
        tool_name: "real-estate"
      });
  
      return new NextResponse(JSON.stringify({ listing }), {
        status: 200,
        headers: { "Content-Type": "application/json" },
      });  } catch (error) {
    console.error(error);
    return new NextResponse(JSON.stringify({ error: "Failed to generate listing." }), {
      status: 500,
      headers: { "Content-Type": "application/json" },
    });
  }
}